INSERT INTO `Job_Offer` VALUES ('adc7be20-6672-11ed-b67e-0242ac110003','Spoed! Afdeling KW Fulltimer (Ervaring is een pre)','Ben jij sociaal? Gek op regelen? En een geboren leider? Dan zoekt Coop jou! Als 1e verkoopmedewerker kruidenierswaren/Vers zorg jij ervoor dat op de afdeling kruidenierswaren en de afdeling vers alles van a tot z geregeld is. Jouw afdeling ziet er 24/7 piekfijn uit. Met je team bestel, ontvang en controleer je goederen en zorg je ervoor dat de schappen goed gevuld zijn, zodat klanten nooit misgrijpen. Je geeft klanten advies, beantwoordt vragen en zorgt ervoor dat zij met een glimlach boodschappen doen. Elke dag opnieuw verras jij onze klanten met een topafdeling!','<p><strong>Jij:</strong></p><ul><li>Bent klantvriendelijk en flexibel</li><li>Vindt het leuk om mensen aan te sturen en te coachen</li><li>Hebt bij voorkeur ervaring in een soortgelijke functie</li><li>Hecht veel waarde aan details</li><li>Hebt een representatieve uitstraling</li><li>Bent leergierig en enthousiast</li><li>Kunt goed samenwerken</li><li>Hebt minimaal een MBO-3 diploma&nbsp;</li></ul><p>Heb je (nog) geen MBO-3 diploma? Coop biedt medewerkers met ambitie de mogelijkheid om zich verder te ontwikkelen. Via <u>Coop College</u> kun je werken en leren combineren en zo je MBO-3 diploma halen.</p>','<p><strong>Wij bieden jou:</strong></p><p>Coop zorgt goed voor haar medewerkers. We bieden jou een marktconform salaris en prima arbeidsvoorwaarden. Maar ook: een goede werksfeer en enthousiaste collega’s. Werken moet tenslotte ook leuk zijn. Iedere dag is anders in onze winkels. Dat betekent veel afwisseling én uitdaging. Bovendien profiteer je van onze uitgebreide opleidings- en doorgroeimogelijkheden, zodat je je kunt blijven ontwikkelen.</p><p>Zie jij een baan als 1e verkoopmedewerker kruidenierswaren /Vers wel zitten? Reageer dan direct.</p>','2022-11-30 00:00:00','36-40','2022-11-17 04:23:44','2022-11-17 04:23:44',NULL,'31bc6562-6672-11ed-b67e-0242ac110003');
/*!40000 ALTER TABLE `Job_Offer` ENABLE KEYS */;

